using System.Security.Claims;
using System.Security.Cryptography;
using System.Text.Json;
using Mes.Api.Data;
using Mes.Api.Security;
using Microsoft.EntityFrameworkCore;
using static Mes.Api.MasterData.Endpoints;
namespace Mes.Api.Sop;
public static class Endpoints
{
    public static string FilesRoot(IConfiguration c)=>Operations.StoragePaths.Get(c,"Sop");
    public static void MapSop(this WebApplication app)
    {
        app.MapGet("/api/sop/versions",async(MesDb db)=>await db.Set<SopVersion>().OrderByDescending(x=>x.Version).Select(v=>new{version=v,files=db.Set<SopFile>().Where(f=>f.SopVersionId==v.Id).OrderBy(f=>f.Position).ToList()}).ToListAsync()).RequireAuthorization("Office");
        app.MapPost("/api/sop/versions",async(JsonElement j,ClaimsPrincipal p,MesDb db)=>{var process=Id(j,"processStepId");Guard.Check(await db.Set<ProcessStep>().AnyAsync(x=>x.Id==process),"工序不存在");var v=new SopVersion{ProcessStepId=process,Version=(await db.Set<SopVersion>().Where(x=>x.ProcessStepId==process).MaxAsync(x=>(int?)x.Version)??0)+1,Title=Str(j,"title"),CreatedBy=p.UserId()};db.Add(v);await db.SaveChangesAsync();return Results.Ok(v);}).RequireAuthorization("Quality");
        app.MapPost("/api/sop/versions/{id:guid}/files",async(Guid id,HttpRequest request,MesDb db,IConfiguration c)=>{
            var version=await db.Set<SopVersion>().FindAsync(id);Guard.Check(version?.Status=="Draft","仅草稿可上传文件");
            var form=await request.ReadFormAsync();Guard.Check(form.Files.Count is >0 and <=30&&form.Files.Sum(f=>f.Length)<=256*1024*1024,"每批最多 30 个文件、合计不超过 256 MB");
            var start=await db.Set<SopFile>().Where(f=>f.SopVersionId==id).CountAsync();var written=new List<string>();
            try{foreach(var f in form.Files){Guard.Check(f.Length>0,"文件不能为空");await using var input=f.OpenReadStream();var header=new byte[16];var read=await input.ReadAsync(header);input.Position=0;
                var type=read>=8&&header[0]==137&&header[1]==80&&header[2]==78&&header[3]==71?"image/png":read>=3&&header[0]==255&&header[1]==216&&header[2]==255?"image/jpeg":read>=5&&System.Text.Encoding.ASCII.GetString(header,0,5)=="%PDF-"?"application/pdf":read>=12&&System.Text.Encoding.ASCII.GetString(header,4,4)=="ftyp"?"video/mp4":read>=4&&header[0]==0x1a&&header[1]==0x45&&header[2]==0xdf&&header[3]==0xa3?"video/webm":"";
                Guard.Check(type!="","只接受 PNG/JPEG/PDF/MP4/WebM，文件签名不匹配");var name=Guid.NewGuid().ToString("N");var path=Path.Combine(FilesRoot(c),name);await using(var output=File.Create(path)){await input.CopyToAsync(output);}written.Add(path);
                await using var stream=File.OpenRead(path);var hash=Convert.ToHexString(await SHA256.HashDataAsync(stream));db.Add(new SopFile{SopVersionId=id,Name=Path.GetFileName(f.FileName),StorageName=name,ContentType=type,Sha256=hash,Size=f.Length,Position=start++,Seconds=10});
            }await db.SaveChangesAsync();return Results.Ok();}catch{foreach(var path in written)File.Delete(path);throw;}
        }).RequireAuthorization("Quality");
        app.MapPut("/api/sop/versions/{id:guid}/files",async(Guid id,JsonElement j,MesDb db)=>{var v=await db.Set<SopVersion>().FindAsync(id);Guard.Check(v?.Status=="Draft","仅草稿可以调整顺序与停留时间");var files=await db.Set<SopFile>().Where(f=>f.SopVersionId==id).ToListAsync();var rows=j.EnumerateArray().ToArray();Guard.Check(rows.Length==files.Count&&rows.Select(x=>Id(x,"id")).Distinct().Count()==files.Count,"必须包含全部文件且不重复");for(int n=0;n<rows.Length;n++){var r=rows[n];var f=files.SingleOrDefault(f=>f.Id==Id(r,"id"));Guard.Check(f!=null,"文件不属于该版本");var seconds=Num(r,"seconds");Guard.Check(seconds is >=1 and <=3600,"停留时间必须为 1–3600 秒");f!.Position=n;f.Seconds=seconds;}await db.SaveChangesAsync();return Results.Ok();}).RequireAuthorization("Quality");
        app.MapPost("/api/sop/versions/{id:guid}/review",async(Guid id,ClaimsPrincipal p,MesDb db)=>{var v=await db.Set<SopVersion>().FindAsync(id);Guard.Check(v?.Status=="Draft"&&await db.Set<SopFile>().AnyAsync(f=>f.SopVersionId==id),"草稿必须有文件才可审核");Guard.Check(v!.CreatedBy!=p.UserId(),"审核人须与创建人不同","separation_of_duties",409);v.Status="Reviewed";v.ReviewedBy=p.UserId();await db.SaveChangesAsync();return Results.Ok();}).RequireAuthorization("Quality");
        app.MapPost("/api/sop/versions/{id:guid}/publish",async(Guid id,MesDb db)=>{var v=await db.Set<SopVersion>().FindAsync(id);Guard.Check(v?.Status=="Reviewed","必须审核通过才能发布","not_reviewed",409);foreach(var old in await db.Set<SopVersion>().Where(x=>x.ProcessStepId==v!.ProcessStepId&&x.Status=="Published").ToListAsync())old.Status="Archived";v!.Status="Published";v.PublishedAt=DateTimeOffset.UtcNow;await db.SaveChangesAsync();return Results.Ok();}).RequireAuthorization("Quality");
        app.MapGet("/api/sop/current/{process:guid}",async(Guid process,ClaimsPrincipal p,MesDb db)=>{await ProcessAccess(p,process,db);var v=await db.Set<SopVersion>().SingleOrDefaultAsync(x=>x.ProcessStepId==process&&x.Status=="Published");return Results.Ok(new{version=v,files=v==null?[]:await db.Set<SopFile>().Where(f=>f.SopVersionId==v.Id).OrderBy(f=>f.Position).ToListAsync()});}).RequireAuthorization("ReadProduction");
        app.MapGet("/api/sop/files/{id:guid}",async(Guid id,ClaimsPrincipal p,MesDb db,IConfiguration c)=>{var f=await db.Set<SopFile>().FindAsync(id);Guard.Check(f!=null,"文件不存在","not_found",404);var v=await db.Set<SopVersion>().FindAsync(f!.SopVersionId);await ProcessAccess(p,v!.ProcessStepId,db);if(p.IsInRole("Operator"))Guard.Check(v.Status is "Published" or "Archived","未发布 SOP 不可读取","forbidden",403);return Results.File(Path.Combine(FilesRoot(c),f.StorageName),f.ContentType,enableRangeProcessing:true);}).RequireAuthorization("ReadProduction");
        app.MapGet("/api/messages",async(ClaimsPrincipal p,MesDb db)=>{var uid=p.UserId();var lines=from g in db.Set<StationGrant>() join s in db.Set<Station>() on g.StationId equals s.Id where g.UserId==uid select s.LineId;return await db.Set<Message>().Where(m=>p.IsInRole("Admin")||p.IsInRole("Supervisor")||p.IsInRole("Quality")||m.LineId==null||lines.Contains(m.LineId.Value)).OrderByDescending(m=>m.At).Take(100).Select(m=>new{message=m,acked=db.Set<MessageAck>().Any(a=>a.MessageId==m.Id&&a.UserId==uid)}).ToListAsync();}).RequireAuthorization("ReadProduction");
        app.MapPost("/api/messages",async(JsonElement j,ClaimsPrincipal p,MesDb db)=>{var m=new Message{Title=Str(j,"title"),Body=Str(j,"body"),CreatedBy=p.UserId(),Important=j.GetProperty("important").GetBoolean(),LineId=j.TryGetProperty("lineId",out var l)&&l.ValueKind==JsonValueKind.String?l.GetGuid():null};db.Add(m);await db.SaveChangesAsync();return Results.Ok(m);}).RequireAuthorization("Manage");
        app.MapPost("/api/messages/{id:guid}/ack",async(Guid id,ClaimsPrincipal p,MesDb db)=>{var m=await db.Set<Message>().FindAsync(id);Guard.Check(m!=null,"消息不存在");var uid=p.UserId();if(p.IsInRole("Operator")&&m!.LineId.HasValue)Guard.Check(await (from g in db.Set<StationGrant>() join s in db.Set<Station>() on g.StationId equals s.Id where g.UserId==uid&&s.LineId==m.LineId select g).AnyAsync(),"未授权确认该产线消息","forbidden",403);if(!await db.Set<MessageAck>().AnyAsync(a=>a.MessageId==id&&a.UserId==uid))db.Add(new MessageAck{MessageId=id,UserId=uid});await db.SaveChangesAsync();return Results.Ok();}).RequireAuthorization("ReadProduction");
        app.MapGet("/api/messages/{id:guid}/acks",async(Guid id,MesDb db)=>await (from a in db.Set<MessageAck>() join u in db.Users on a.UserId equals u.Id where a.MessageId==id select new{a.At,u.Account,u.Name}).ToListAsync()).RequireAuthorization("Office");
    }
    static async Task ProcessAccess(ClaimsPrincipal p,Guid process,MesDb db){Guard.Check(!p.IsInRole("TV"),"大屏账号不可读取 SOP 文件","forbidden",403);if(p.IsInRole("Operator"))Guard.Check(await (from g in db.Set<StationGrant>() join s in db.Set<Station>() on g.StationId equals s.Id where g.UserId==p.UserId()&&s.ProcessStepId==process select g).AnyAsync(),"未授权该工序","forbidden",403);}
}
